 		ret = __add_reloc_root(reloc_root, rc);
@@ -5659,15 +5679,17 @@ int btrfs_recover_relocation(struct btrfs_fs_info *fs_info)
 			list_add_tail(&reloc_root->root_list, &reloc_roots);
 			btrfs_put_root(fs_root);
